insert into public.split_muscle_targets (split_day_id, muscle_name, priority) select id, 'Lateral deltoid', 12 from public.split_days where split_id='phat' and day_of_week='Saturday' on conflict (split_day_id, muscle_name) do update set priority=excluded.priority;
